#include <zephyr/kernel.h>
#include <zephyr/ztest.h>

#define STACK_SIZE (512 + CONFIG_TEST_EXTRA_STACK_SIZE)

static K_THREAD_STACK_DEFINE(tstack, STACK_SIZE);
static struct k_thread tdata;

static K_SEM_DEFINE(sem, 0, 1);
static K_FIFO_DEFINE(fifo);
static K_LIFO_DEFINE(lifo);
static K_STACK_DEFINE(stack, 4);
static K_MSGQ_DEFINE(msgq, 1, 1, 1);
static K_MBOX_DEFINE(mbox);
static K_PIPE_DEFINE(pipe, 1, 1);
static K_MUTEX_DEFINE(mutex);

struct q_item {
	sys_slist_t snode;
};

static struct q_item qdata;

/* Helper thread that pends on multiple object types */
static void t_pending_entry(void *p1, void *p2, void *p3)
{
	uintptr_t obj_type = (uintptr_t)p1;
	char data;
	stack_data_t sdata;
	struct k_mbox_msg msg = {0};
	size_t size;

	switch (obj_type) {
	case 1:
		k_sem_take(&sem, K_FOREVER);
		break;
	case 2:
		zassert_true(k_fifo_get(&fifo, K_FOREVER) == &qdata, NULL);
		break;
	case 3:
		zassert_true(k_lifo_get(&lifo, K_FOREVER) == &qdata, NULL);
		break;
	case 4:
		k_stack_pop(&stack, &sdata, K_FOREVER);
		break;
	case 5:
		k_msgq_get(&msgq, &data, K_FOREVER);
		break;
	case 6:
		k_mbox_get(&mbox, &msg, &data, K_FOREVER);
		break;
	case 7:
		k_pipe_get(&pipe, &data, 1, &size, K_FOREVER);
		break;
	case 8:
		k_mutex_lock(&mutex, K_FOREVER);
		k_mutex_unlock(&mutex);
		break;
	default:
		ztest_test_fail();
	}
}

static void start_pending_thread(uintptr_t obj_type)
{
	k_thread_create(&tdata, tstack, STACK_SIZE, t_pending_entry,
			(void *)obj_type, NULL, NULL,
			K_PRIO_PREEMPT(0), 0, K_NO_WAIT);
	/* Let the thread run and pend */
	k_yield();
}

/**
 * @brief Test if a thread is correctly pending on a semaphore
 * @ingroup kernel_thread_tests
 * @see k_sem_take()
 */
ZTEST(pending, test_pending_sem)
{
	start_pending_thread(1);
	zassert_equal(tdata.pended_on, &sem.wait_q, "thread not pending on sem");
	k_sem_give(&sem);
	k_thread_join(&tdata, K_FOREVER);
}

/**
 * @brief Test if a thread is correctly pending on a FIFO
 * @ingroup kernel_thread_tests
 * @see k_fifo_get()
 */
ZTEST(pending, test_pending_fifo)
{
	start_pending_thread(2);
	zassert_equal(tdata.pended_on, &fifo.wait_q, "thread not pending on fifo");
	k_fifo_put(&fifo, &qdata);
	k_thread_join(&tdata, K_FOREVER);
}

/**
 * @brief Test if a thread is correctly pending on a LIFO
 * @ingroup kernel_thread_tests
 * @see k_lifo_get()
 */
ZTEST(pending, test_pending_lifo)
{
	start_pending_thread(3);
	zassert_equal(tdata.pended_on, &lifo.wait_q, "thread not pending on lifo");
	k_lifo_put(&lifo, &qdata);
	k_thread_join(&tdata, K_FOREVER);
}

/**
 * @brief Test if a thread is correctly pending on a stack
 * @ingroup kernel_thread_tests
 * @see k_stack_pop()
 */
ZTEST(pending, test_pending_stack)
{
	start_pending_thread(4);
	zassert_equal(tdata.pended_on, &stack.wait_q, "thread not pending on stack");
	k_stack_push(&stack, 0);
	k_thread_join(&tdata, K_FOREVER);
}

/**
 * @brief Test if a thread is correctly pending on a message queue
 * @ingroup kernel_thread_tests
 * @see k_msgq_get()
 */
ZTEST(pending, test_pending_msgq)
{
	char data;

	start_pending_thread(5);
	zassert_equal(tdata.pended_on, &msgq.wait_q, "thread not pending on msgq");
	k_msgq_put(&msgq, &data, K_NO_WAIT);
	k_thread_join(&tdata, K_FOREVER);
}

/**
 * @brief Test if a thread is correctly pending on a mailbox
 * @ingroup kernel_thread_tests
 * @see k_mbox_get()
 */
ZTEST(pending, test_pending_mbox)
{
	struct k_mbox_msg msg = {0};

	start_pending_thread(6);
	zassert_equal(tdata.pended_on, &mbox.wait_q, "thread not pending on mbox");
	k_mbox_put(&mbox, &msg, K_NO_WAIT);
	k_thread_join(&tdata, K_FOREVER);
}

/**
 * @brief Test if a thread is correctly pending on a pipe
 * @ingroup kernel_thread_tests
 * @see k_pipe_get()
 */
ZTEST(pending, test_pending_pipe)
{
	char data;
	size_t size;

	start_pending_thread(7);
	zassert_equal(tdata.pended_on, &pipe.wait_q, "thread not pending on pipe");
	k_pipe_put(&pipe, &data, 1, &size, K_NO_WAIT);
	k_thread_join(&tdata, K_FOREVER);
}

/**
 * @brief Test if a thread is correctly pending on a mutex
 * @ingroup kernel_thread_tests
 * @see k_mutex_lock()
 */
ZTEST(pending, test_pending_mutex)
{
	k_mutex_lock(&mutex, K_FOREVER);
	start_pending_thread(8);
	zassert_equal(tdata.pended_on, &mutex.wait_q, "thread not pending on mutex");
	k_mutex_unlock(&mutex);
	k_thread_join(&tdata, K_FOREVER);
}

ZTEST_SUITE(pending, NULL, NULL, NULL, NULL, NULL);
